// web/src/middleware/auth.ts (excerpt, original file is ~240 LOC)
export async function middleware(req: NextRequest) {
  const access = req.cookies.get("access_token")?.value
  const refresh = req.cookies.get("refresh_token")?.value
  const res = NextResponse.next()

  if (!access && refresh) {
    const refreshed = await refreshSession(refresh)
    if (refreshed.ok) {
      res.cookies.set("access_token", refreshed.accessToken, {
        httpOnly: true,
        sameSite: "lax",
        path: "/",
      })
      req.headers.set("x-user-id", refreshed.userId)
    } else {
      res.cookies.delete("access_token")
      res.cookies.delete("refresh_token")
    }
  }

  return res
}

// web/src/lib/auth-client.ts (excerpt)
let inflightRefresh: Promise<RefreshResult> | null = null

export async function getSession() {
  const res = await fetch("/api/auth/session", { credentials: "include" })
  if (res.status === 401) {
    if (!inflightRefresh) {
      inflightRefresh = fetch("/api/auth/refresh", {
        method: "POST",
        credentials: "include",
      }).then(r => r.json()).finally(() => {
        inflightRefresh = null
      })
    }
    await inflightRefresh
    return fetch("/api/auth/session", { credentials: "include" }).then(r => r.json())
  }
  return res.json()
}

// web/src/app/api/auth/refresh/route.ts (excerpt)
export async function POST(req: NextRequest) {
  const refresh = req.cookies.get("refresh_token")?.value
  const rotated = await authService.rotate(refresh)
  const res = NextResponse.json({ ok: rotated.ok, userId: rotated.userId })
  if (!rotated.ok) {
    res.cookies.delete("access_token")
    res.cookies.delete("refresh_token")
    return res
  }
  res.cookies.set("access_token", rotated.accessToken, { httpOnly: true, path: "/" })
  return res
}

