// web/src/hooks/usePresence.ts (excerpt, original file is ~190 LOC)
export function usePresence(session: Session | null) {
  const [status, setStatus] = useState<"idle" | "open" | "closed">("idle")
  const socketRef = useRef<WebSocket | null>(null)

  useEffect(() => {
    if (!session?.user?.id) return
    socketRef.current = new WebSocket(`/ws/presence?user=${session.user.id}`)
    socketRef.current.onopen = () => setStatus("open")
    socketRef.current.onclose = () => setStatus("closed")
    return () => socketRef.current?.close()
  }, [session])

  useEffect(() => {
    if (status !== "open") return
    const id = setInterval(() => socketRef.current?.send(JSON.stringify({ t: "ping" })), 15000)
    return () => clearInterval(id)
  }, [status, session])
}

// web/src/hooks/usePresence.ts after first pass
export function usePresence(session: Session | null) {
  const userId = session?.user?.id
  const socketRef = useRef<WebSocket | null>(null)
  const [status, setStatus] = useState<"idle" | "open" | "closed">("idle")

  useEffect(() => {
    if (!userId) return
    const ws = new WebSocket(`/ws/presence?user=${userId}`)
    socketRef.current = ws
    ws.onopen = () => setStatus("open")
    ws.onclose = () => setStatus("closed")
    document.addEventListener("visibilitychange", () => {
      if (document.visibilityState === "visible") ws.send(JSON.stringify({ t: "resume" }))
    })
    return () => ws.close()
  }, [userId])
}

