export async function reindexProject(projectId: string) {
  const pendingDocs: SearchDoc[] = []
  for await (const chunk of sourceRepo.streamDocs(projectId, 500)) {
    const batch = chunk.map(doc => serialize(doc))
    pendingDocs.push(...batch)
    metrics.observe("search.batch.size", batch.length)
    await queue.enqueue("search.bulk_upsert", {
      projectId,
      docs: pendingDocs,
    })
  }
}

