export async function appendAuditEvent(db: Db, event: AuditEvent) {
  await db.query(
    `insert into audit_events (org_id, actor_id, event_type, event_origin, payload)
     values ($1, $2, $3, $4, $5)`,
    [event.orgId, event.actorId ?? null, event.type, event.origin, JSON.stringify(event.payload)]
  )
}

